const job = $json;

// =====================================
// DATA RELEVANCE FILTER V1.1
// =====================================

// =====================================
// 0. NORMALIZACIÓN DE TEXTO
// =====================================

function normalizar(texto = '') {
  return texto
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const titulo = normalizar(job.puesto || '');
const descripcion = normalizar(job.descripcion || '');
const texto = `${titulo} ${descripcion}`;

function contiene(textoBase, termino) {
  const t = normalizar(termino);
  return textoBase.includes(t);
}

function buscarCoincidencias(textoBase, lista) {
  return lista.filter(keyword => contiene(textoBase, keyword));
}

// =====================================
// 1. FAMILIAS DE ROL OBJETIVO
// =====================================

const titulosObjetivo = [
  // Data Analysis
  'data analyst',
  'analista de datos',
  'data analytics analyst',
  'data analytics specialist',
  'data analytics',

  // Business Intelligence
  'business intelligence analyst',
  'business intelligence specialist',
  'bi analyst',
  'analista bi',
  'analista de business intelligence',

  // Reporting
  'reporting analyst',
  'analista de reporting',
  'reporting specialist',
  'analista de reportes',

  // Business Analytics
  'business analytics analyst',
  'business analytics specialist',

  // Operations Analytics
  'operations analytics analyst',
  'operations analytics',
  'operational analytics',
  'analista de analitica de operaciones',

  // Otros roles analíticos cercanos
  'performance analyst',
  'insights analyst',
  'analytics analyst'
];

const coincidenciasTitulo =
  buscarCoincidencias(titulo, titulosObjetivo);

// =====================================
// 2. TÍTULOS AMBIGUOS
// =====================================

const titulosAmbiguos = [
  'business analyst',
  'analista de negocio',
  'analista de negocios',

  // V1.1: permite evaluar Analista Funcional
  // mediante evidencia adicional de Data
  'analista funcional',
  'functional analyst',

  'operations analyst',
  'operational analyst',
  'analista de operaciones',

  'commercial analyst',
  'analista comercial',

  'sales analyst',
  'analista de ventas',

  'performance analyst',
  'analista de performance'
];

const coincidenciasTituloAmbiguo =
  buscarCoincidencias(titulo, titulosAmbiguos);

const esTituloAmbiguo =
  coincidenciasTituloAmbiguo.length > 0;

// =====================================
// 3. HERRAMIENTAS DATA / BI
// =====================================

const herramientasData = [
  'sql',
  'postgresql',
  'mysql',

  'power bi',
  'powerbi',
  'tableau',
  'looker',
  'looker studio',
  'qlik',

  'excel',
  'power query',
  'dax',

  'python',
  'pandas',

  'bigquery',
  'snowflake',
  'redshift'
];

const coincidenciasHerramientas =
  buscarCoincidencias(texto, herramientasData);

const tieneHerramientasData =
  coincidenciasHerramientas.length > 0;

// =====================================
// 4. SEÑALES DE ANÁLISIS DE DATOS
// =====================================

const senalesAnalisis = [
  'analisis de datos',
  'data analysis',
  'data analytics',
  'analitica de datos',

  'business intelligence',

  'data-driven',
  'data driven',
  'insights',
  'business insights',

  'analisis estadistico',
  'statistical analysis',

  'analisis exploratorio',
  'exploratory data analysis',

  'tendencias',
  'trends',
  'patterns',
  'patrones'
];

const coincidenciasAnalisis =
  buscarCoincidencias(texto, senalesAnalisis);

const tieneAnalisis =
  coincidenciasAnalisis.length > 0;

// =====================================
// 5. REPORTING / DASHBOARDS / KPIs
// =====================================

const senalesReporting = [
  'dashboard',
  'dashboards',

  'reporting',
  'reportes',
  'reports',

  'kpi',
  'kpis',
  'indicadores',

  'metricas',
  'metrics',

  'data visualization',
  'visualizacion de datos',

  'business reporting',
  'performance reporting',

  'performance analysis',
  'analisis de desempeno',

  'business review',
  'performance tracking'
];

const coincidenciasReporting =
  buscarCoincidencias(texto, senalesReporting);

const tieneReporting =
  coincidenciasReporting.length > 0;

// =====================================
// 6. PREPARACIÓN / TRANSFORMACIÓN
// =====================================

const senalesPreparacionDatos = [
  'data cleaning',
  'limpieza de datos',

  'data cleansing',
  'data preparation',
  'preparacion de datos',

  'data transformation',
  'transformacion de datos',

  'etl',

  'data modeling',
  'data modelling',
  'modelado de datos',

  'data warehouse',
  'data warehousing',

  'data quality',
  'calidad de datos'
];

const coincidenciasPreparacionDatos =
  buscarCoincidencias(texto, senalesPreparacionDatos);

const tienePreparacionDatos =
  coincidenciasPreparacionDatos.length > 0;

// =====================================
// 7. NEGOCIO / OPERACIONES
// =====================================

const senalesNegocio = [
  'business performance',
  'sales performance',
  'operational performance',

  'business planning',
  'decision making',
  'toma de decisiones',

  'operaciones',
  'operations',

  'process improvement',
  'mejora de procesos',
  'continuous improvement',
  'mejora continua',

  'stakeholders',
  'business requirements',

  'ecommerce',
  'e-commerce',

  'customer experience',
  'customer operations'
];

const coincidenciasNegocio =
  buscarCoincidencias(texto, senalesNegocio);

const tieneNegocio =
  coincidenciasNegocio.length > 0;

// =====================================
// 8. AUTOMATIZACIÓN
// =====================================

const senalesAutomatizacion = [
  'automation',
  'automatizacion',
  'reporting automation',
  'automatizacion de reportes',
  'workflow automation',
  'power automate',
  'power apps',
  'n8n'
];

const coincidenciasAutomatizacion =
  buscarCoincidencias(texto, senalesAutomatizacion);

const tieneAutomatizacion =
  coincidenciasAutomatizacion.length > 0;

// =====================================
// 9. PERFILES TÉCNICOS NO PRIORITARIOS
// =====================================

const tecnicosNoPrioritarios = [
  'data engineer',
  'ingeniero de datos',

  'machine learning engineer',
  'ml engineer',

  'data scientist',
  'cientifico de datos',

  'ai engineer',
  'artificial intelligence engineer',

  'mlops engineer',

  'software engineer',
  'ingeniero de software',

  'backend engineer',
  'backend developer',

  'frontend developer',
  'frontend engineer',

  'full stack',
  'fullstack',

  'devops engineer',

  'database administrator',
  'dba'
];

const coincidenciasTecnicas =
  buscarCoincidencias(titulo, tecnicosNoPrioritarios);

const esTecnicoNoPrioritario =
  coincidenciasTecnicas.length > 0;

// =====================================
// 9.1 V1.1 — ML / DATA SCIENCE POR FUNCIÓN
// =====================================

// V1 solo detectaba perfiles técnicos por título.
// V1.1 también detecta cuando una vacante con título
// aparentemente BI/Data tiene como función CENTRAL
// Machine Learning / Data Science.
//
// Importante:
// una sola mención de ML NO bloquea la vacante.

const senalesMLDataScience = [
  'machine learning',
  'aprendizaje automatico',
  'data science',
  'ciencia de datos',
  'modelos predictivos',
  'predictive models',
  'predictive modeling',
  'predictive modelling',
  'modelos de machine learning',
  'machine learning models',
  'entrenamiento de modelos',
  'model training'
];

const coincidenciasMLDataScience =
  buscarCoincidencias(descripcion, senalesMLDataScience);

// Exigimos al menos 2 señales diferentes.
// Esto evita bloquear un Data Analyst simplemente
// porque la descripción menciona ML una vez.

const funcionMLDataScience =
  coincidenciasMLDataScience.length >= 2;

// =====================================
// 10. PILARES DATA
// =====================================

const pilares = [
  tieneHerramientasData,
  tieneAnalisis,
  tieneReporting,
  tienePreparacionDatos
].filter(Boolean).length;

// =====================================
// 11. SCORE DE RELEVANCIA
// =====================================

let score = 0;

// Título objetivo = señal más fuerte
if (coincidenciasTitulo.length > 0) score += 5;

// Título ambiguo aporta poco por sí mismo
if (esTituloAmbiguo) score += 1;

// Señales funcionales
if (tieneHerramientasData) score += 2;
if (tieneAnalisis) score += 2;
if (tieneReporting) score += 2;
if (tienePreparacionDatos) score += 1;

// Contexto de negocio
if (tieneNegocio) score += 1;

// Automatización como complemento
if (tieneAutomatizacion) score += 1;

// Combinaciones especialmente relevantes
if (tieneHerramientasData && tieneAnalisis) score += 1;
if (tieneHerramientasData && tieneReporting) score += 1;
if (tieneAnalisis && tieneReporting) score += 1;

// Penalizaciones
if (esTecnicoNoPrioritario) score -= 6;

// V1.1
if (funcionMLDataScience) score -= 6;

// =====================================
// 12. LÓGICA DE RELEVANCIA
// =====================================

// Caso A:
// título inequívocamente Data / BI
const rolObjetivoDirecto =
  coincidenciasTitulo.length > 0;

// Caso B:
// título ambiguo + evidencia Data suficiente
const rolAmbiguoConData =
  esTituloAmbiguo &&
  pilares >= 2 &&
  (
    tieneHerramientasData ||
    tieneAnalisis
  );

// Caso C:
// título no previsto pero descripción
// claramente orientada a Analytics
const rolDataPorContenido =
  coincidenciasTitulo.length === 0 &&
  !esTituloAmbiguo &&
  pilares >= 3 &&
  tieneHerramientasData &&
  (
    tieneAnalisis ||
    tieneReporting
  );

// =====================================
// 12.1 V1.1 — ROL HÍBRIDO DATA + AUTOMATION
// =====================================

// Recupera perfiles como:
// Business Analyst / Analista Funcional
// con una combinación real de Data +
// automatización + negocio/procesos.
//
// No basta con que aparezca "automation".

const rolHibridoDataAutomation =
  esTituloAmbiguo &&
  tieneAutomatizacion &&
  (
    tieneHerramientasData ||
    tienePreparacionDatos ||
    tieneAnalisis
  ) &&
  tieneNegocio;

const encajaTematicamente =
  rolObjetivoDirecto ||
  rolAmbiguoConData ||
  rolDataPorContenido ||
  rolHibridoDataAutomation;

// =====================================
// 13. DECISIÓN FINAL
// =====================================

const relevante =
  encajaTematicamente &&
  !esTecnicoNoPrioritario &&
  !funcionMLDataScience &&
  score >= 5;

// =====================================
// 14. SALIDA
// =====================================

return {
  json: {
    ...job,

    prefiltro: {
      version: 'Data Relevance Filter V1.1',

      relevante,
      score,
      pilares_detectados: pilares,

      tipo_match: {
        rol_objetivo_directo: rolObjetivoDirecto,
        rol_ambiguo_con_data: rolAmbiguoConData,
        rol_data_por_contenido: rolDataPorContenido,
        rol_hibrido_data_automation: rolHibridoDataAutomation
      },

      coincidencias_titulo: coincidenciasTitulo,
      coincidencias_titulo_ambiguo: coincidenciasTituloAmbiguo,

      categorias: {
        herramientas_data: tieneHerramientasData,
        analisis: tieneAnalisis,
        reporting_bi: tieneReporting,
        preparacion_datos: tienePreparacionDatos,
        negocio_operaciones: tieneNegocio,
        automatizacion: tieneAutomatizacion,
        tecnico_no_prioritario: esTecnicoNoPrioritario,
        funcion_ml_data_science: funcionMLDataScience
      },

      bloqueos: {
        tecnico_no_prioritario: esTecnicoNoPrioritario,
        funcion_ml_data_science: funcionMLDataScience
      },

      coincidencias: {
        herramientas_data: coincidenciasHerramientas,
        analisis: coincidenciasAnalisis,
        reporting_bi: coincidenciasReporting,
        preparacion_datos: coincidenciasPreparacionDatos,
        negocio_operaciones: coincidenciasNegocio,
        automatizacion: coincidenciasAutomatizacion,
        tecnico_titulo: coincidenciasTecnicas,
        ml_data_science_funcion: coincidenciasMLDataScience
      }
    }
  }
};

