const data = $json.output;
const e = data.evaluacion;


// ==============================
// ESCALAS
// ==============================

const escalas25 = {
  alta: 25,
  media_alta: 20,
  media: 15,
  baja: 8,
  nula: 0,
};

const escalas15 = {
  alta: 15,
  media_alta: 12,
  media: 9,
  baja: 5,
  nula: 0,
};

const escalas10 = {
  alta: 10,
  media_alta: 8,
  media: 6,
  baja: 3,
  nula: 0,
};

const escalasCompat10 = {
  compatible: 10,
  parcial: 5,
  no_compatible: 0,
};

const escalasCompat5 = {
  compatible: 5,
  parcial: 2,
  no_compatible: 0,
};


// ==============================
// SCORE POR DIMENSIÓN
// ==============================

const scoreDetalle = {
  experiencia_relacionada:
    escalas25[e.experiencia_relacionada] ?? 0,

  herramientas_tecnologias:
    escalas25[e.herramientas_tecnologias] ?? 0,

  responsabilidades:
    escalas15[e.responsabilidades] ?? 0,

  industria_contexto:
    escalas10[e.industria_contexto] ?? 0,

  seniority:
    escalasCompat10[e.seniority] ?? 0,

  idioma:
    escalasCompat5[e.idioma] ?? 0,

  modalidad_ubicacion:
    escalasCompat5[e.modalidad_ubicacion] ?? 0,

  salario:
    escalasCompat5[e.salario] ?? 0,
};


// ==============================
// SCORE BASE
// ==============================

const scoreBase = Object.values(scoreDetalle)
  .reduce((total, valor) => total + valor, 0);


// ==============================
// DATOS CRÍTICOS
// ==============================

const requisitosCriticos =
  Array.isArray(data.requisitos_criticos_faltantes)
    ? data.requisitos_criticos_faltantes
    : [];

const tecnologiasNucleoFaltantes =
  Array.isArray(data.tecnologias_nucleo_faltantes)
    ? data.tecnologias_nucleo_faltantes
    : [];

const tieneRequisitoExcluyente =
  data.tiene_requisito_excluyente === true;


// ==============================
// PENALIZACIONES
// ==============================

let penalizacion = 0;

// Penalización moderada por requisitos obligatorios faltantes.
// El cap evita que una lista larga distorsione excesivamente el score.
penalizacion += Math.min(
  requisitosCriticos.length * 3,
  12
);


// ==============================
// SCORE AJUSTADO
// ==============================

let compatibilidad = Math.max(
  0,
  scoreBase - penalizacion
);


// ==============================
// REGLAS DE CONTROL
// ==============================

// Un requisito excluyente hace que la vacante
// no sea viable para el candidato.
if (tieneRequisitoExcluyente) {
  compatibilidad = Math.min(compatibilidad, 59);
}


// Una tecnología núcleo faltante requiere revisión.
if (tecnologiasNucleoFaltantes.length === 1) {
  compatibilidad = Math.min(compatibilidad, 79);
}


// Dos tecnologías núcleo faltantes representan
// un gap técnico considerable.
if (tecnologiasNucleoFaltantes.length === 2) {
  compatibilidad = Math.min(compatibilidad, 69);
}


// Tres o más tecnologías núcleo faltantes
// hacen que el ajuste técnico sea insuficiente.
if (tecnologiasNucleoFaltantes.length >= 3) {
  compatibilidad = Math.min(compatibilidad, 59);
}


// Si la compatibilidad general de herramientas
// es baja o nula, no puede recomendarse Aplicar.
if (
  e.herramientas_tecnologias === 'baja' ||
  e.herramientas_tecnologias === 'nula'
) {
  compatibilidad = Math.min(compatibilidad, 79);
}


// ==============================
// RECOMENDACIÓN
// ==============================

let recomendacion;

if (compatibilidad >= 80) {
  recomendacion = 'Aplicar';
} else if (compatibilidad >= 60) {
  recomendacion = 'Revisar';
} else {
  recomendacion = 'Descartar';
}


// ==============================
// OUTPUT
// ==============================

return {
  json: {
    vacante: {
  ...$('Analizar Vacante con IA').item.json.output,
  query_origen:
  $('Preparar Vacante SerpApi para Análisis').item.json.query_origen || ''
    },

    score_base: scoreBase,
    penalizacion,
    compatibilidad,

    score_detalle: scoreDetalle,

    fortalezas:
      data.fortalezas || [],

    habilidades_faltantes:
      data.habilidades_faltantes || [],

    requisitos_criticos_faltantes:
      requisitosCriticos,

    tecnologias_nucleo_faltantes:
      tecnologiasNucleoFaltantes,

    tiene_requisito_excluyente:
      tieneRequisitoExcluyente,

    motivo_requisito_excluyente:
      data.motivo_requisito_excluyente || '',

    recomendacion,

    motivo_recomendacion:
      data.motivo_recomendacion || ''
  }
};

const item = $json;

function normalizar(texto = '') {
  return texto
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const empresa = normalizar(item.empresa);
const puesto = normalizar(item.puesto);
const ubicacion = normalizar(item.ubicacion);

const job_id = `${empresa}__${puesto}__${ubicacion}`;

return {
  json: {
    ...item,
    job_id
  }
};

const normalize = (value = '') => {
  return String(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

return items.map(item => {
  const empresa = normalize(item.json.empresa);
  const puesto = normalize(item.json.puesto);
  const ubicacion = normalize(item.json.ubicacion);

  const job_hash = `${empresa}|${puesto}|${ubicacion}`;

  return {
    json: {
      ...item.json,
      job_hash
    }
  };
});

const vacantes = items.map(item => item.json);

// ==============================
// ORDENAR POR COMPATIBILIDAD
// ==============================

vacantes.sort(
  (a, b) =>
    Number(b.compatibilidad || 0) -
    Number(a.compatibilidad || 0)
);

// ==============================
// CLASIFICAR
// ==============================

const aplicar = vacantes.filter(
  v => v.recomendacion === 'Aplicar'
);

const revisar = vacantes.filter(
  v => v.recomendacion === 'Revisar'
);

const descartadas = vacantes.filter(
  v => v.recomendacion === 'Descartar'
);

// Vacantes que sí queremos mostrar individualmente
const oportunidades = [
  ...aplicar,
  ...revisar
];

// ==============================
// UTILIDADES
// ==============================

function escapeHtml(texto = '') {
  return String(texto)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function convertirLista(valor) {
  if (Array.isArray(valor)) {
    return valor;
  }

  if (!valor) {
    return [];
  }

  try {
    const parsed = JSON.parse(valor);
    return Array.isArray(parsed) ? parsed : [valor];
  } catch {
    return [valor];
  }
}

function crearLista(valor, limite = 3) {
  const lista = convertirLista(valor)
    .filter(Boolean)
    .slice(0, limite);

  if (lista.length === 0) {
    return '';
  }

  return lista
    .map(elemento => `• ${escapeHtml(elemento)}`)
    .join('<br>');
}

function crearSalario(v) {
  const min = Number(v.salario_min || 0);
  const max = Number(v.salario_max || 0);

  if (min === 0 && max === 0) {
    return '';
  }

  const moneda =
    v.moneda && v.moneda !== 'No especificado'
      ? escapeHtml(v.moneda)
      : '';

  const periodicidad =
    v.periodicidad_salario &&
    v.periodicidad_salario !== 'No especificado'
      ? ` / ${escapeHtml(v.periodicidad_salario)}`
      : '';

  if (min > 0 && max > 0 && min !== max) {
    return `
      <p style="margin:4px 0;">
        💰 ${min.toLocaleString()} - ${max.toLocaleString()} ${moneda}${periodicidad}
      </p>
    `;
  }

  const salario = min || max;

  return `
    <p style="margin:4px 0;">
      💰 ${salario.toLocaleString()} ${moneda}${periodicidad}
    </p>
  `;
}

// ==============================
// TARJETA DE VACANTE
// ==============================

function crearVacante(v) {

  const puesto =
    escapeHtml(v.puesto || 'Puesto no especificado');

  const empresa =
    escapeHtml(v.empresa || 'Empresa no especificada');

  const ubicacion =
    escapeHtml(v.ubicacion || 'No especificada');

  const modalidad =
    escapeHtml(v.modalidad || 'No especificada');

  const recomendacion =
    escapeHtml(v.recomendacion || '');

  const compatibilidad =
    Number(v.compatibilidad || 0);

  const scoreBase =
    Number(v.score_base || 0);

  const url =
    v.url_aplicar || v.url || '#';

  const fortalezas =
    crearLista(v.fortalezas, 3);

  const gapsCriticos =
    crearLista(v.requisitos_criticos_faltantes, 3);

  const tecnologiasFaltantes =
    crearLista(v.tecnologias_nucleo_faltantes, 3);

  const gapsGenerales =
    crearLista(v.habilidades_faltantes, 3);

  const motivo =
    v.motivo_recomendacion
      ? escapeHtml(v.motivo_recomendacion)
      : '';

  return `
    <div style="
      margin-bottom:24px;
      padding:18px;
      border:1px solid #ddd;
      border-radius:10px;
    ">

      <h3 style="margin:0 0 8px 0;">
        ${puesto}
      </h3>

      <p style="margin:4px 0;">
        <strong>${empresa}</strong>
      </p>

