const resultados = [];
const vistos = new Set();

for (const item of items) {
  const jobs = item.json.jobs_results || [];

  const query =
    item.json.search_parameters?.q ||
    item.json.search_parameters?.query ||
    '';

  for (const job of jobs) {
    const id =
      job.job_id ||
      `${job.title}|${job.company_name}|${job.location}`;

    if (vistos.has(id)) {
      continue;
    }

    vistos.add(id);

    resultados.push({
      json: {
        ...job,
        query_origen: query
      }
    });
  }
}

return resultados;

// ======================================================
// AI CAREER COPILOT
// Deduplicación en memoria contra el CRM
// ======================================================

// Vacantes que pasaron el prefiltro
const vacantes = $('Validar Relevancia de Vacante')
  .all()
  .map(item => item.json);

// Filas existentes recuperadas del CRM
const crm = $('Leer Vacantes Existentes del CRM')
  .all()
  .map(item => item.json);


// ------------------------------------------------------
// 1. Normalización
// ------------------------------------------------------

function normalizar(valor) {
  return String(valor ?? '').trim();
}


// ------------------------------------------------------
// 2. Crear índices de registros existentes
// ------------------------------------------------------

const sourceIdsExistentes = new Set(
  crm
    .map(row => normalizar(row.source_job_id))
    .filter(Boolean)
);

const hashesExistentes = new Set(
  crm
    .map(row => normalizar(row.job_hash))
    .filter(Boolean)
);


// ------------------------------------------------------
// 3. Deduplicar
// ------------------------------------------------------

const vacantesNuevas = [];

const sourceIdsVistos = new Set();
const hashesVistos = new Set();

for (const vacante of vacantes) {

  const sourceJobId = normalizar(vacante.source_job_id);
  const jobHash = normalizar(vacante.job_hash);

  // Ya existe en el CRM por ID exacto
  const duplicadaPorSourceId =
    sourceJobId &&
    sourceIdsExistentes.has(sourceJobId);

  // Ya existe en el CRM por hash
  const duplicadaPorHash =
    jobHash &&
    hashesExistentes.has(jobHash);

  if (duplicadaPorSourceId || duplicadaPorHash) {
    continue;
  }

  // --------------------------------------------------
  // 4. Evitar duplicados dentro de ESTA ejecución
  // --------------------------------------------------

  const repetidaEnEjecucionPorSourceId =
    sourceJobId &&
    sourceIdsVistos.has(sourceJobId);

  const repetidaEnEjecucionPorHash =
    jobHash &&
    hashesVistos.has(jobHash);

  if (
    repetidaEnEjecucionPorSourceId ||
    repetidaEnEjecucionPorHash
  ) {
    continue;
  }

  // Registrar como vista
  if (sourceJobId) {
    sourceIdsVistos.add(sourceJobId);
  }

  if (jobHash) {
    hashesVistos.add(jobHash);
  }

  // Vacante realmente nueva
  vacantesNuevas.push({
    json: {
      ...vacante,
      deduplicacion: {
        nueva: true,
        source_job_id_verificado: Boolean(sourceJobId),
        job_hash_verificado: Boolean(jobHash)
      }
    }
  });
}


// ------------------------------------------------------
// 5. Salida
// ------------------------------------------------------

return vacantesNuevas;
